<template><section class="hero"><div class="wrap hero-grid"><div><div class="eyebrow">Football tips, made clear</div><h1>Follow the picks.<br/>Back the track record.</h1><p>Discover BraTips tipsters, see today's featured picks and follow prediction performance before you decide what to play.</p><div class="hero-actions"><RouterLink to="/bet-of-the-day" class="btn">See Bet of the Day</RouterLink><RouterLink to="/tipsters" class="ghost">Explore tipsters</RouterLink></div></div><div class="hero-card"><h3>Today's BraTips edge</h3><div v-if="bot.length"><div v-for="p in bot" :key="p._id" style="padding:12px 0;border-top:1px solid #eee"><b>{{matchName(p.matchId)}}</b><div style="display:flex;justify-content:space-between;margin-top:6px"><span>{{p.prediction}}</span><strong>{{p.confidence}}%</strong></div></div></div><div v-else class="muted">No featured picks published yet.</div></div></div></section><section class="section"><div class="wrap"><div class="section-head"><div><h2>Latest tipster picks</h2><div class="muted">Public to browse. Sign up to play a pick.</div></div><RouterLink to="/picks" class="small">View all →</RouterLink></div><div class="grid3"><PickCard v-for="p in picks.slice(0,6)" :key="p._id" :pick="p" @play="play"/></div></div></section><section class="section"><div class="wrap"><div class="banners"><div class="stat"><span class="muted small">Why BraTips</span><b>Transparent</b><span class="muted small">See past wins and losses.</span></div><div class="stat"><span class="muted small">Daily feature</span><b>2 picks</b><span class="muted small">AI-assisted Bet of the Day.</span></div><div class="stat"><span class="muted small">Tipster rewards</span><b>Earn</b><span class="muted small">Winning streaks can qualify for prizes.</span></div></div></div></section></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import {RouterLink,useRouter} from 'vue-router';import {api} from '../services/api';import PickCard from '../components/PickCard.vue';const picks=ref<any[]>([]),bot=ref<any[]>([]),router=useRouter();const matchName=(m:any)=>m?.homeTeamId?.name&&m?.awayTeamId?.name?`${m.homeTeamId.name} vs ${m.awayTeamId.name}`:'Featured match';function play(){router.push({path:'/login',query:{redirect:'/dashboard'}})}onMounted(async()=>{try{picks.value=(await api.get('/predictions?limit=6')).data}catch{}try{bot.value=(await api.get('/bet-of-day')).data}catch{}})</script>
